#include <cstdio>

using namespace std;

const int K = 25;
const int N = 505;
const int E = N << 1;

int n, m, k;
int h[N], to[E], nx[E], et;
int f[K][N][N];

void ae(int u, int v) {
    et++;
    to[et] = v;
    nx[et] = h[u];
    h[u] = et;
}

int main() {
    scanf("%d%d%d", &n, &m, &k);
    for (int i = 1; i <= m; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        ae(u, v);
        ae(v, u);
    }
    for (int i = 1; i <= n; i++)
        f[0][i][i] = 1;
    for (int t = 1; t <= k; t++)
        for (int x = 1; x <= n; x++)
            for (int y = 1; y <= n; y++)
                if (f[t - 1][x][y])
                    for (int i = h[y]; i; i = nx[i])
                        f[t][x][to[i]] = 1;
    for (int i = 1; i <= n; i++) {
        for (int t = 1; t <= k; t++) {
            int ans = 0;
            for (int j = 1; j <= n; j++)
                ans += f[t][i][j];
            printf("%d%c", ans, " \n"[t == k]);
        }
    }
    return 0;
}

